import{_ as a,a0 as n,w as u,s as l,ao as p,I as d,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Ubuntu 上為用户授予和移除 sudo 權限 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上為用户授予和移除 sudo 權限 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上為用户授予和移除 sudo 權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上為用户授予和移除 sudo 權限 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu","title":"如何在 Ubuntu 上為用户授予和移除 sudo 權限","tag":"201902","desc":""},"relativePath":"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu.md","filePath":"[post].md"}'),r={name:"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu.md"};function h(c,s,g,b,k,f){const o=n("Link");return u(),l("div",null,[s[15]||(s[15]=p(`<h1 id="如何在-ubuntu-上為用户授予和移除-sudo-權限" tabindex="-1">如何在 Ubuntu 上為用户授予和移除 sudo 權限 <a class="header-anchor" href="#如何在-ubuntu-上為用户授予和移除-sudo-權限" aria-label="Permalink to “如何在 Ubuntu 上為用户授予和移除 sudo 權限”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/sudo-privileges-720x340.png" alt=""></p><p>如你所知，用户可以在 Ubuntu 系統上使用 sudo 權限執行任何管理任務。在 Linux 機器上創建新用户時，他們無法執行任何管理任務，直到你將其加入 <code>sudo</code> 組的成員。在這個簡短的教程中，我們將介紹如何將普通用户添加到 <code>sudo</code> 組以及移除給定的權限，使其成為普通用户。</p><h3 id="在-linux-上向普通用户授予-sudo-權限" tabindex="-1">在 Linux 上向普通用户授予 sudo 權限 <a class="header-anchor" href="#在-linux-上向普通用户授予-sudo-權限" aria-label="Permalink to “在 Linux 上向普通用户授予 sudo 權限”">​</a></h3><p>通常，我們使用 <code>adduser</code> 命令創建新用户，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo adduser ostechnix</span></span></code></pre></div><p>如果你希望新創建的用户使用 <code>sudo</code> 執行管理任務，只需使用以下命令將它添加到 <code>sudo</code> 組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G sudo hduser</span></span></code></pre></div><p>上面的命令將使名為 <code>ostechnix</code> 的用户成為 <code>sudo</code> 組的成員。</p><p>你也可以使用此命令將用户添加到 <code>sudo</code> 組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo adduser ostechnix sudo</span></span></code></pre></div><p>現在，註銷並以新用户身份登錄，以使此更改生效。此時用户已成為管理用户。</p><p>要驗證它，只需在任何命令中使用 <code>sudo</code> 作為前綴。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /test</span></span>
<span class="line"><span>[sudo] password for ostechnix:</span></span></code></pre></div><h3 id="移除用户的-sudo-權限" tabindex="-1">移除用户的 sudo 權限 <a class="header-anchor" href="#移除用户的-sudo-權限" aria-label="Permalink to “移除用户的 sudo 權限”">​</a></h3><p>有時，你可能希望移除特定用户的 <code>sudo</code> 權限，而不用在 Linux 中刪除它。要將任何用户設為普通用户，只需將其從 <code>sudo</code> 組中刪除即可。</p><p>比如説如果要從 <code>sudo</code> 組中刪除名為 <code>ostechnix</code> 的用户，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo deluser ostechnix sudo</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Removing user \`ostechnix&#39; from group \`sudo&#39; ...</span></span>
<span class="line"><span>Done.</span></span></code></pre></div><p>此命令僅從 <code>sudo</code> 組中刪除用户 <code>ostechnix</code>，但不會永久地從系統中刪除用户。現在，它成為了普通用户，無法像 <code>sudo</code> 用户那樣執行任何管理任務。</p><p>此外，你可以使用以下命令撤消用户的 <code>sudo</code> 訪問權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo gpasswd -d ostechnix sudo</span></span></code></pre></div><p>從 <code>sudo</code> 組中刪除用户時請小心。不要從 <code>sudo</code> 組中刪除真正的管理員。</p><p>使用命令驗證用户 <code>ostechnix</code> 是否已從 <code>sudo</code> 組中刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -l -U ostechnix</span></span>
<span class="line"><span>User ostechnix is not allowed to run sudo on ubuntuserver.</span></span></code></pre></div><p>是的，用户 <code>ostechnix</code> 已從 <code>sudo</code> 組中刪除，他無法執行任何管理任務。</p><p>從 <code>sudo</code> 組中刪除用户時請小心。如果你的系統上只有一個 <code>sudo</code> 用户，並且你將他從 <code>sudo</code> 組中刪除了，那麼就無法執行任何管理操作，例如在系統上安裝、刪除和更新程序。所以，請小心。在我們的下一篇教程中，我們將解釋如何恢復用户的 <code>sudo</code> 權限。</p><p>就是這些了。希望這篇文章有用。還有更多好東西。敬請期待！</p><p>乾杯!</p><hr>`,31)),d("p",null,[s[1]||(s[1]=e("via: ",-1)),i(o,{href:"https://www.ostechnix.com/how-to-grant-and-remove-sudo-privileges-to-users-on-ubuntu/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/how-to-grant-and-remove-sudo-privileges-to-users-on-ubuntu/",-1)])]),_:1})]),d("p",null,[s[6]||(s[6]=e("作者：",-1)),i(o,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),d("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=a(r,[["render",h]]);export{v as __pageData,C as default};
